const agora = DateTime.now().setZone('America/Sao_Paulo');

return [{ json: {
  // WF018, assim como WF016, é um workflow de escopo GLOBAL (não recebe id_empresa) -
  // 'GLOBAL' é um valor explícito e documentado, nunca uma string vazia silenciosa.
  id_empresa: 'GLOBAL',
  agora_iso: agora.toISO(),
  // Retenção de LOGS: decisão técnica conservadora e documentada (não há regra de negócio
  // definida no projeto para retenção de logs) - mesma lógica usada nas janelas de detecção
  // dos WF013/WF014/WF015. Ajustável conforme decisão futura do proprietário.
  retencao_dias_logs: 90
} }];

const ctx = $('CODE - Preparar Limpeza').first().json;

// Este node só recebe o output de SUCESSO de "GS - Buscar Todos Os Logs" (o erro técnico
// tem seu próprio caminho dedicado em "CODE - Erro Leitura Logs", com node_origem correto -
// mesma correção aplicada ao WF016 nesta revisão, para não usar "0 itens" como proxy de erro).
// alwaysOutputData garante >=1 item mesmo com a aba LOGS vazia (placeholder {}); linhas sem
// ID_LOG (o placeholder) são descartadas abaixo, então "linhas.length === 0" aqui significa
// genuinamente "nenhum log gravado ainda", não erro técnico.
const linhas = items.map(i => i.json).filter(x => x && x.ID_LOG);

const agora = ctx.agora_iso ? DateTime.fromISO(ctx.agora_iso, { zone: 'America/Sao_Paulo' }) : DateTime.now().setZone('America/Sao_Paulo');
const retencaoDias = ctx.retencao_dias_logs;

const expirados = linhas.filter(l => {
  if (!l.DATA_HORA) return false; // sem data confiável, nunca excluir
  const dataLog = DateTime.fromISO(String(l.DATA_HORA), { zone: 'America/Sao_Paulo' });
  if (!dataLog.isValid) return false; // data ilegível, nunca excluir
  if (typeof l.row_number !== 'number') return false; // sem o número exato da linha, nunca excluir
  const idadeDias = agora.diff(dataLog, 'days').days;
  return idadeDias > retencaoDias;
});

// Ordena do maior row_number para o menor: como cada exclusão desloca as linhas
// seguintes para cima, processar do fim para o começo garante que os row_number já
// calculados aqui continuem válidos para os itens ainda não processados neste mesmo lote.
expirados.sort((a, b) => b.row_number - a.row_number);

if (expirados.length === 0) {
  return [{ json: { ...ctx, tem_expirados: false, limpeza_erro: '', total_logs_lidos: linhas.length } }];
}

return expirados.map(l => ({ json: {
  ...ctx, tem_expirados: true, limpeza_erro: '', total_logs_lidos: linhas.length,
  row_number_excluir: l.row_number, id_log_excluir: l.ID_LOG
} }));

const ctx = $('CODE - Preparar Limpeza').first().json;
const err = $json.error || {};

return [{ json: {
  ...ctx, tem_expirados: false,
  node_origem: 'GS - Buscar Todos Os Logs',
  limpeza_erro: String((err && err.message) || err || 'Falha técnica ao ler a aba LOGS para aplicar a retenção.')
} }];

// Mesmo padrão simples e seguro já usado em ADM-WF016 (CODE - Marcar Exclusão OK/Falhou):
// apenas contabiliza, sem tentar referenciar de volta o item de origem por índice
// (evita ambiguidade de pareamento quando múltiplos logs expirados são excluídos na mesma
// execução em modo "run once for all items").
return items.map(() => ({ json: { excluido: true } }));

const ctx = $('CODE - Preparar Limpeza').first().json;

let excluidos = 0, falhas = 0;
let limpezaErro = '';
let totalLogsLidos;
let nodeOrigemHerdado = '';

for (const it of items) {
  const j = it.json;
  if (j.limpeza_erro) limpezaErro = j.limpeza_erro;
  if (typeof j.total_logs_lidos === 'number') totalLogsLidos = j.total_logs_lidos;
  if (j.node_origem) nodeOrigemHerdado = j.node_origem;
  if (j.excluido === true) excluidos++;
  else if (j.excluido === false) falhas++;
  // "excluido" ausente => ramo "sem expirados" ou "erro de leitura", não conta.
}

let node_origem;
if (limpezaErro) {
  // Erro ocorreu na leitura da aba LOGS (node_origem já veio marcado por CODE - Erro Leitura Logs).
  node_origem = nodeOrigemHerdado || 'GS - Buscar Todos Os Logs';
} else if (falhas > 0) {
  node_origem = 'GS - Excluir Log Expirado';
} else {
  node_origem = 'CODE - Selecionar Logs Expirados';
}

const evento_resultado = limpezaErro ? 'ERRO_LIMPEZA' : 'LIMPEZA_CONCLUIDA';

return [{ json: {
  id_empresa: ctx.id_empresa,
  agora_iso: ctx.agora_iso,
  retencao_dias_logs: ctx.retencao_dias_logs,
  evento_resultado,
  node_origem,
  limpeza_erro: limpezaErro,
  total_logs_lidos: totalLogsLidos,
  logs_excluidos: excluidos,
  logs_com_falha_exclusao: falhas
} }];
